/* ══════════════════════════════════════════════
   💪 إرسال تفاعل — يعرض فوق صورة اللاعب
   ══════════════════════════════════════════════ */
async function unoSendReaction(emoji){
  const m = state.activeUnoMatch;
  if(!m || !m.unoState) return;

  showUnoReactionOverAvatar(state.user.uid, emoji);

  try {
    await updateDoc(doc(db, 'rooms', m.roomId), {
      'unoState.lastReaction': {
        uid: state.user.uid,
        emoji,
        at: Date.now(),
        id: Date.now() + '_' + Math.random().toString(36).slice(2, 8),
      },
    });
  } catch(e){
    console.error('reaction:', e);
  }
}

/* ══════════════════════════════════════════════
   🎭 عرض الإيموجي طائراً فوق الصورة
   ══════════════════════════════════════════════ */
/* ✅ FIX 3: عرض الإيموجي في طبقة ثابتة فوق كل شيء */
function showUnoReactionOverAvatar(uid, emoji){
  let avatarEl = null;

  if(uid === state.user.uid){
    avatarEl = document.querySelector('.uno-my-avatar');
  } else {
    avatarEl = document.querySelector(`.uno-seat [data-view-profile="${uid}"]`);
  }

  if(!avatarEl) return;

  /* احسب موضع الصورة الفعلي على الشاشة */
  const rect = avatarEl.getBoundingClientRect();
  const centerX = rect.left + rect.width / 2;
  const topY = rect.top;

  const el = document.createElement('div');
  el.className = 'uno-floating-reaction';
  el.textContent = emoji;
  el.style.left = centerX + 'px';
  el.style.top = topY + 'px';

  /* ✅ يُضاف إلى body — يبقى حتى لو renderUnoGame أعاد رسم الـ container */
  document.body.appendChild(el);

  setTimeout(() => {
    try { el.remove(); } catch(e){}
  }, 1900);
}

/* ══════════════════════════════════════════════
   🔔 إعلان UNO
   ══════════════════════════════════════════════ */
async function unoCallUno(){
  const m = state.activeUnoMatch;
  if(!m || !m.unoState) return;
  const me = state.user.uid;
  const myHand = m.unoState.hands[me] || [];
  if(myHand.length !== 1) return toast('لا يمكنك إعلان UNO الآن');

  try {
    const roomRef = doc(db,'rooms', m.roomId);
    await updateDoc(roomRef, {
      [`unoState.unoCalled.${me}`]: true,
    });
    toast('🔔 UNO!');
  } catch(e){
    console.error(e);
  }
}

/* ══════════════════════════════════════════════
   ⏰ انتهاء الوقت — مع تتبع الخصم
   ══════════════════════════════════════════════ */
async function handleUnoTimeout(roomId){
  const m = state.activeUnoMatch;
  if(!m || !m.unoState) return;

  try {
    const roomRef = doc(db, 'rooms', roomId);
    await runTransaction(db, async tx => {
      const snap = await tx.get(roomRef);
      if(!snap.exists()) throw new Error('room deleted');
      const data = snap.data();
      const st = data.unoState;
      if(!st || st.finished) throw new Error('finished');

      const current = st.playerOrder[st.currentTurn];
      const timeouts = { ...(st.timeoutCounts || {}) };
      const newCount = (timeouts[current] || 0) + 1;

      /* ★ إذا مرتين متتاليتين → استسلام */
      if(newCount >= 2){
        const winner = st.playerOrder.find(u => u !== current) || null;
        tx.update(roomRef, {
          'unoState.finished': true,
          'unoState.winnerId': winner,
          'unoState.finishReason': 'timeout',
          [`unoState.timeoutCounts.${current}`]: newCount,
        });
        return;
      }

      /* ★ المرة الأولى → سحب ورقة + انتقال الدور */
      const newDeck = [...st.deck];
      const newHands = { ...st.hands };
      const myHand = [...(newHands[current] || [])];

      if(newDeck.length === 0){
        const reshuffled = st.discard.slice(0, -1);
        newDeck.push(...unoShuffle(reshuffled));
      }
      if(newDeck.length > 0) myHand.push(newDeck.shift());
      newHands[current] = myHand;

      const nextTurn = (st.currentTurn + st.direction + st.playerOrder.length) % st.playerOrder.length;

      tx.update(roomRef, {
        'unoState.deck': newDeck,
        'unoState.hands': newHands,
        'unoState.currentTurn': nextTurn,
        'unoState.turnStartedAt': Date.now(),
        'unoState.turnCount': st.turnCount + 1,
        [`unoState.timeoutCounts.${current}`]: newCount,
      });
    });
  } catch(e){
    if(e.message !== 'finished' && e.message !== 'room deleted'){
      console.error('handleUnoTimeout:', e);
    }
  }
}

/* ══════════════════════════════════════════════
   ⏱️ مؤقت الدور
   ══════════════════════════════════════════════ */
function startUnoTurnTimer(roomId){
  if(state.unoTimer) clearInterval(state.unoTimer);
  state.unoTimer = setInterval(() => {
    const m = state.activeUnoMatch;
    if(!m || !m.unoState || m.unoState.finished){ 
      clearInterval(state.unoTimer); 
      return; 
    }

    const s = m.unoState;
    const me = state.user.uid;
    const isMyTurn = s.playerOrder[s.currentTurn] === me;
    const elapsed = (Date.now() - s.turnStartedAt) / 1000;
    const remaining = Math.max(0, s.turnTime - elapsed);
    const pct = Math.max(0, Math.min(100, (remaining / s.turnTime) * 100));
    const color = pct > 50 ? '#22c55e' : pct > 20 ? '#f5b031' : '#ff3d71';
    const progressDeg = pct * 3.6;  /* 0–360 */

    /* ✅ إطار الخصم النشط */
    const activeRing = document.querySelector('.uno-seat.active .uno-avatar-timer');
    if(activeRing){
      activeRing.style.setProperty('--progress-deg', `${progressDeg}deg`);
      activeRing.style.setProperty('--timer-color', color);
    }

    /* ✅ إطاري (إذا كان دوري) */
    const myRing = document.querySelector('.uno-my-header .uno-avatar-timer');
    if(myRing){
      if(isMyTurn){
        myRing.style.setProperty('--progress-deg', `${progressDeg}deg`);
        myRing.style.setProperty('--timer-color', color);
      } else {
        myRing.style.setProperty('--progress-deg', '0deg');
        myRing.style.setProperty('--timer-color', 'transparent');
      }
    }

    /* ✅ السحب التلقائي عند انتهاء الوقت */
    if(remaining <= 0 && isMyTurn && !s.finished){
      const turnKey = `${s.currentTurn}_${s.turnStartedAt}`;
      if(state._unoAutoDrawForTurn !== turnKey){
        state._unoAutoDrawForTurn = turnKey;
        handleUnoTimeout(roomId);
      }
    }
  }, 250);
}

/* ══════════════════════════════════════════════
   🏆 شاشة النتيجة
   ══════════════════════════════════════════════ */
async function unoShowResult(roomId){
  const m = state.activeUnoMatch;
  if(!m || !m.unoState) return;
  const winnerId = m.unoState.winnerId;
  const finishReason = m.unoState.finishReason;
  const teams = m.unoState.teams || {};
  const myTeam = teams[state.user.uid];
  const isWinner = winnerId === state.user.uid ||
    (myTeam && teams[winnerId] === myTeam);
  const winnerUser = state.users[winnerId] || { name:'لاعب' };

  /* ★ سبب الفوز */
  const reasonText = finishReason === 'timeout'
    ? '⏰ بسبب استسلام الخصم (تجاوز الوقت مرتين)'
    : finishReason === 'empty-hand'
      ? '🎴 تخلّص من كل أوراقه أولاً'
      : '';
  const isTeamWin = myTeam && teams[winnerId] === myTeam;

  /* XP/عملات */
  try {
    await updateDoc(doc(db,'users',state.user.uid), {
      xp:    increment(isWinner ? 150 : 30),
      coins: increment(isWinner ? 200 : 50),
      fame:  increment(isWinner ? 30  : 5),
    });
    await addDoc(collection(db,'users',state.user.uid,'matchHistory'), {
      gameId:'uno',
      gameName:'أونو',
      roomId,
      result: isWinner ? 'win' : 'loss',
      myScore: isWinner ? 1 : 0,
      opponentScore: isWinner ? 0 : 1,
      mode: m.unoState.mode,
      playedAt: serverTimestamp(),
    });
  } catch(e){ console.warn('uno reward:', e); }

  const container = document.getElementById('gameContainer');
  if(!container) return;
  container.innerHTML = `
    <div class="uno-result">
      <div class="uno-result-icon">${isWinner ? '🏆' : '🎴'}</div>
      <h1 class="uno-result-title" style="color:${isWinner ? 'var(--gold)' : 'var(--muted)'}">
        ${isWinner ? 'فوز رائع!' : `${esc(winnerUser.name)} فاز`}
      </h1>
      <div class="uno-result-sub">
        ${isWinner ? '+200 عملة · +150 XP' : '+50 عملة · +30 XP'}
      </div>
      <div class="uno-result-actions">
        <button class="btn btn-primary" data-action="uno-play-again">
          ${ic('play','sm')} مباراة أخرى
        </button>
        <button class="btn btn-ghost" data-action="uno-exit">
          العودة للألعاب
        </button>
      </div>
    </div>
  `;
}

/* ══════════════════════════════════════════════
   🚪 الخروج
   ══════════════════════════════════════════════ */
function unoExitMatch(){
  /* ★ إغلاق أي مودال مفتوح أولاً */
  closeModal();

  if(state.unoUnsub){ try{state.unoUnsub();}catch(e){} state.unoUnsub = null; }
  if(state.unoChatUnsub){ try{state.unoChatUnsub();}catch(e){} state.unoChatUnsub = null; }
  if(state.unoTimer){ clearInterval(state.unoTimer); state.unoTimer = null; }
  if(state._unoMatchingUnsub){
    try { state._unoMatchingUnsub(); } catch(e){}
    state._unoMatchingUnsub = null;
  }

  state.activeUnoMatch = null;
  state._unoWinnerShown = false;
  state._unoColorPickerOpen = false;
  state._unoPendingWild = null;
  state._unoChatOpen = false;
  state._unoDrawing = false;
  state._unoAutoDrawForTurn = null;
  state.matchChat = [];
  state.unoSelectedMode = null;
  state.unoSettingsEditing = false;
  state._unoSettingsBackup = null;

  document.getElementById('gameOverlay').classList.add('hidden');
  document.body.style.overflow = '';

  /* ★ بعد ثانية، فحص المباريات النشطة (ليظهر البانر لو الغرفة لا تزال نشطة) */
  setTimeout(checkActiveGames, 800);

  render();
}

/* ══════════════════════════════════════════════
   💾 تحميل الإعدادات من قاعدة البيانات
   ══════════════════════════════════════════════ */
function loadUnoSettingsFromDB(){
  if(state.unoSettingsLoaded) return;
  if(!state.profile) return;
  const saved = state.profile.unoSettings;
  if(saved && typeof saved === 'object'){
    state.unoSettings = {
      maxPlayers:  Number(saved.maxPlayers)  || 4,
      initialHand: Number(saved.initialHand) || 7,
      turnTime:    Number(saved.turnTime)    || 30,
      teamMode:    saved.teamMode || 'ffa',      /* ★ */
      isPublic:    saved.isPublic !== false,
      password:    typeof saved.password === 'string' ? saved.password : '',
    };
    state.unoHasCustomSettings = true;
  }
  state.unoSettingsLoaded = true;
}

async function persistUnoSettings(){
  if(!state.user?.uid) return false;
  try {
    await updateDoc(doc(db, 'users', state.user.uid), {
      unoSettings: {
        maxPlayers:  state.unoSettings.maxPlayers,
        initialHand: state.unoSettings.initialHand,
        turnTime:    state.unoSettings.turnTime,
        teamMode:    state.unoSettings.teamMode,   /* ★ */
        isPublic:    state.unoSettings.isPublic,
        password:    state.unoSettings.password,
      },
    });
    if(state.profile) state.profile.unoSettings = { ...state.unoSettings };
    state.unoHasCustomSettings = true;
    return true;
  } catch(e){ console.warn('persistUnoSettings:', e); return false; }
}
