    if(field === 'profileLayout'  && !canUseLayoutCustomization(state.profile)){ toast('🔒 التخطيط يتطلب بلس دبل'); return; }
    if(field === 'bannerEffect'   && !canUseBannerEffect(state.profile))   { toast('🔒 تأثيرات الغلاف تتطلب بلس'); return; }
